// Admin login (generated by `lila admin --react`). POST {prefix}/login -> {"success", "redirect"}.
import type { ReactElement } from "react";
import { Card, Form, Input, SubmitButton, ThemeToggle, Toaster } from "../../components/ui";

export default function AdminLogin({ prefix }: { prefix: string }) {
  return (
    <main className="relative flex min-h-screen items-center justify-center px-4">
      <ThemeToggle className="absolute right-4 top-4" />
      <Card className="w-full max-w-sm" title="Lila Admin" description="Sign in to manage your data">
        <Form action={`${prefix}/login`} initial={{ username: "", password: "" }} redirect={prefix}>
          <Input name="username" label="User" required autoComplete="username" placeholder="admin" />
          <Input name="password" type="password" label="Password" required autoComplete="current-password" />
          <SubmitButton loadingText="Signing in...">Sign in</SubmitButton>
        </Form>
      </Card>
      <Toaster />
    </main>
  );
}

AdminLogin.layout = (page: ReactElement) => page;
